  tbody tr[data-highlight] th { font-weight: 800; }
  .table-foot { border-top: 1px solid var(--line); padding: .65rem 1.15rem; color: var(--muted); font-size: .825rem; }
  .notes { margin-block: 3rem 3.5rem; padding-top: 1.25rem; border-top: 1px solid var(--line); }
  .notes h2 { font-size: 1.65rem; }
  .notes-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem 2rem; margin-top: .7rem; color: var(--muted); font-size: .885rem; }
  .notes strong { color: var(--ink); }
  .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
  .print-only, .short { display: none; }
  @media (max-width: 53rem) {
    .wrap { width: calc(100% - 2.5rem); }
    .hero { gap: 1.75rem; }
    .formats { gap: .6rem; }
    .format { padding: .85rem; }
    th, td { padding-inline: .7rem; }
  }
  @media screen and (max-width: 40rem) {
    .wrap { width: calc(100% - 2rem); }
    .masthead .wrap { gap: 0 .75rem; padding-block: .5rem; }
    nav { gap: .85rem; flex-wrap: wrap; }
    .hero, .formats, .notes-grid { grid-template-columns: 1fr; }
    .section { padding-top: 2.5rem; }
    .filters { padding: .75rem; column-gap: .65rem; }
    .results-count { margin-left: 0; }
    th, td { padding: .6rem .28rem; font-size: .8125rem; text-align: center; }
    thead th { font-size: .75rem; line-height: 1.25; }
