    .table-foot { padding-inline: .75rem; }
  }
  @media print {
    @page { margin: .55in; }
    :root { background: white; font-size: 10pt; print-color-adjust: exact; }
    .wrap { width: 100%; }
    .masthead .wrap { min-height: 2rem; }
    nav, .skip, .filters, #export, #screen-rows, .screen-only { display: none; }
    .print-only { display: revert; }
    .hero { padding-block: 1rem; grid-template-columns: 1fr 1.15fr; gap: 1rem; }
    h1 { font-size: 34pt; }
    h2 { font-size: 19pt; }
    .intro { margin-top: .6rem; font-size: 10pt; }
    .recommend { box-shadow: none; padding: .85rem; }
    .recommend h2 { font-size: 17pt; }
    .rec-margins { padding-top: .6rem; margin-top: .65rem; }
    .slots { margin-top: .6rem; }
    .slots li { min-height: 1.45rem; }
    .big-money { font-size: 20pt; }
    .formats { gap: .6rem; }
    .format { padding: .65rem; break-inside: avoid; }
    .facts { margin-top: .55rem; padding-top: .5rem; }
    .section { padding-top: 1.15rem; }
    .section-head { margin-bottom: .65rem; break-after: avoid; }
    th, td { padding: .22rem .5rem; }
    .panel, .table-scroll { overflow: visible; }
    tr { break-inside: avoid; }
    .notes { margin-block: 1rem 0; }
    .alternative, .hero { break-inside: avoid; }
  }
</style>
</head>
<body>
<a class="skip" href="#main">Skip to planner</a>
<header class="masthead">
  <div class="wrap">
    <div class="brand"><span class="mark" aria-hidden="true"></span> Ceramics Studio</div>
    <nav aria-label="Planner sections">
      <a href="#formats">Class formats</a>
      <a href="#mixes">Schedule mixes</a>
      <button id="print" type="button">Print plan</button>
    </nav>
  </div>
</header>
<main class="wrap" id="main">
  <section aria-labelledby="title">
    <div class="hero">
      <div class="hero-copy">
        <p class="eyebrow">Term planning</p>
        <h1 id="title">Next term’s class mix</h1>
        <p class="intro">Six sessions total, including at least two beginner wheel sessions. Compare what each mix leaves after direct costs.</p>
      </div>
      <article class="recommend" aria-labelledby="best-title">
        <p class="eyebrow">Highest projected margin</p>
        <h2 id="best-title"></h2>
        <ol class="slots" id="best-slots" aria-label="Recommended schedule"></ol>
        <dl class="rec-margins">
          <div><dt>Baseline term margin</dt><dd class="big-money" id="best-base"></dd></div>
          <div><dt>With one fewer attendee per class</dt><dd class="big-money" id="best-stress"></dd></div>
        </dl>
      </article>
    </div>
    <aside class="alternative" aria-labelledby="alternative-title">
      <div>
        <h2 id="alternative-title">If you want all three formats</h2>
        <p id="alternative-mix"></p>
      </div>
      <p class="alt-money" id="alternative-money"></p>
    </aside>
    <noscript><p>Enable JavaScript in your browser to calculate and display the comparisons.</p></noscript>
  </section>

  <section class="section" id="formats" aria-labelledby="formats-title">
    <div class="section-head">
      <div>
        <h2 id="formats-title">Margin by class format</h2>
        <p>Projected dollars per session. The bars share a common scale.</p>
      </div>
      <div class="legend" aria-hidden="true">
        <span><i></i> Baseline</span>
        <span><i class="stress"></i> One fewer attendee</span>
      </div>
    </div>
    <div class="formats" id="format-cards"></div>
  </section>

  <section class="section" id="mixes" aria-labelledby="mixes-title">
    <div class="section-head">
      <div>
        <h2 id="mixes-title">Compare six-session mixes</h2>
        <p id="coverage"></p>
      </div>
      <button id="export" type="button">Download all mixes as CSV</button>
    </div>
    <div class="panel">
      <div class="filters">
        <label>Wheel sessions
          <select id="wheel-filter">
            <option value="">Any (2–6)</option>
            <option>2</option><option>3</option><option>4</option><option>5</option><option>6</option>
          </select>
        </label>
        <label>Sort by
          <select id="sort">
            <option value="base">Baseline margin</option>
            <option value="stress">Stress margin</option>
            <option value="drop">Smallest margin drop</option>
          </select>
        </label>
        <label class="checkbox"><input type="checkbox" id="diverse-filter"> Include all three formats</label>
        <p class="results-count" id="results-count" role="status"></p>
      </div>
      <div class="table-scroll" tabindex="0" role="region" aria-label="Schedule mix results">
        <table aria-describedby="table-foot">
          <caption class="sr-only">Projected term margins by class schedule</caption>
          <thead>
            <tr>
              <th scope="col">Wheel</th>
              <th scope="col"><span class="long">Handbuilding</span><span class="short">Hand<span class="sr-only">building</span></span></th>
              <th scope="col">Glazing</th>
              <th scope="col">Baseline<span class="sr-only"> margin</span></th>
              <th scope="col">Stress<span class="sr-only"> margin</span></th>
              <th scope="col">Drop</th>
            </tr>
          </thead>
          <tbody id="screen-rows"></tbody>
          <tbody class="print-only" id="print-rows"></tbody>
        </table>
      </div>
      <p class="table-foot" id="table-foot">Stress margin assumes one fewer attendee in each of the six sessions. Drop is the difference from baseline.</p>
    </div>
  </section>

  <footer class="notes" aria-labelledby="method-title">
    <h2 id="method-title">How the projections work</h2>
    <div class="notes-grid">
      <p><strong>Enrollment.</strong> Baseline uses the exact mean of four fictional historical sessions per format. The stress case subtracts one from each mean. Fractional averages are kept for projections.</p>
      <p><strong>Direct costs.</strong> Session margin is attendance × (price − materials per attendee) − instructor cost. Term margin sums the six session margins. Break-even is the minimum whole-person attendance that covers those costs. Overhead is outside this calculation.</p>
    </div>
  </footer>
</main>
<script>
  const sessionCount = 6;
  const beginnerMinimum = 2;
  const formats = [
    { name: "Beginner wheel", shortName: "wheel", history: [7, 8, 6, 8], price: 45, materials: 9, instructor: 120, beginner: true },
    { name: "Handbuilding", shortName: "handbuilding", history: [5, 6, 4, 6], price: 38, materials: 6, instructor: 95 },
    { name: "Glazing workshop", shortName: "glazing", history: [4, 5, 5, 6], price: 32, materials: 8, instructor: 80 },
  ].map(format => {
    const attendance = format.history.reduce((sum, count) => sum + count, 0) / format.history.length;
    const perAttendee = format.price - format.materials;
    return {
      ...format,
      attendance,
      stressAttendance: attendance - 1,
      base: attendance * perAttendee - format.instructor,
      stress: (attendance - 1) * perAttendee - format.instructor,
      breakEven: Math.ceil(format.instructor / perAttendee),
    };
  });

  const mixes = [];
  for (let wheel = beginnerMinimum; wheel <= sessionCount; wheel++) {
    for (let handbuilding = 0; handbuilding <= sessionCount - wheel; handbuilding++) {
      const glazing = sessionCount - wheel - handbuilding;
      const counts = [wheel, handbuilding, glazing];
      const base = formats.reduce((sum, format, index) => sum + format.base * counts[index], 0);
      const stress = formats.reduce((sum, format, index) => sum + format.stress * counts[index], 0);
      mixes.push({ wheel, handbuilding, glazing, counts, base, stress, drop: base - stress });
    }
  }
  mixes.sort((a, b) => b.base - a.base || b.stress - a.stress);
  const best = mixes[0];
  const diverse = mix => mix.counts.every(count => count > 0);
  const bestDiverse = mixes.find(diverse);

  const byId = id => document.getElementById(id);
  const currency = new Intl.NumberFormat("en-US", {
    style: "currency", currency: "USD", minimumFractionDigits: 0, maximumFractionDigits: 2,
  });
  const dollars = amount => currency.format(amount);

  byId("best-title").textContent = `${best.wheel} beginner wheel sessions`;
  byId("best-slots").innerHTML = Array.from({ length: best.wheel }, () => "<li>Wheel</li>").join("");
  byId("best-base").textContent = dollars(best.base);
  byId("best-stress").textContent = dollars(best.stress);
  byId("alternative-mix").textContent = formats.map((format, index) => `${bestDiverse.counts[index]} ${format.name.toLowerCase()}`).join(" · ");
  byId("alternative-money").innerHTML = `<strong>${dollars(bestDiverse.base)}</strong> baseline · <strong>${dollars(bestDiverse.stress)}</strong> with one fewer per class`;

  const barLimit = Math.ceil(Math.max(...formats.map(format => format.base)) / 10) * 10;
  byId("format-cards").innerHTML = formats.map(format => `
    <article class="format">
      <div class="format-head"><h3>${format.name}</h3>${format.beginner ? '"'<span class=\"tag\">Counts toward minimum</span>' : ''}</div>
      <p class=\"history\">Past enrollments · "'${format.history.join(", ")}</p>
      <div class="plot">
        <div class="plot-row">
          <span class="track" aria-hidden="true"><span class="bar" style="width:${format.base / barLimit * 100}%"></span></span>
          <strong><span class="sr-only">Baseline margin </span>${dollars(format.base)}</strong>
        </div>
        <div class="plot-row">
          <span class="track" aria-hidden="true"><span class="bar stress" style="width:${format.stress / barLimit * 100}%"></span></span>
          <strong><span class="sr-only">Stress margin </span>${dollars(format.stress)}</strong>
        </div>
      </div>
      <dl class="facts">
        <div><dt>Baseline attendance</dt><dd>${format.attendance}</dd></div>
        <div><dt>Stress attendance</dt><dd>${format.stressAttendance}</dd></div>
        <div><dt>Break-even attendance</dt><dd>${format.breakEven}</dd></div>
        <div><dt>Price / materials per person</dt><dd>${dollars(format.price)} / ${dollars(format.materials)}</dd></div>
        <div><dt>Instructor per session</dt><dd>${dollars(format.instructor)}</dd></div>
      </dl>
    </article>
  `).join("");

  const stressMinimum = Math.min(...mixes.map(mix => mix.stress));
  const covered = mixes.filter(mix => mix.stress >= 0).length;
  byId("coverage").textContent = `${covered} of ${mixes.length} eligible mixes cover direct costs under stress. The lowest stress margin is ${dollars(stressMinimum)}.`;

  function renderRows(rows) {
    if (!rows.length) {
      return '"'<tr><td colspan=\"6\">No mixes match these filters.</td></tr>';
    }
    return rows.map(mix => "'`
      <tr ${mix === best ? "data-highlight" : ""}>
        <th scope="row">${mix.wheel}${mix === best ? '"'<span class=\"sr-only\"> (highest projected margin)</span>' : ''}</th>
        <td>"'${mix.handbuilding}</td><td>${mix.glazing}</td>
        <td>${dollars(mix.base)}</td><td>${dollars(mix.stress)}</td><td>${dollars(mix.drop)}</td>
      </tr>
    `).join("");
  }

  const wheelFilter = byId("wheel-filter");
  const diverseFilter = byId("diverse-filter");
  const sort = byId("sort");
  function updateMixes() {
    const filtered = mixes.filter(mix =>
      (!wheelFilter.value || mix.wheel === Number(wheelFilter.value)) &&
      (!diverseFilter.checked || diverse(mix))
    );
    const metric = sort.value;
    filtered.sort((a, b) => metric === "drop" ? a.drop - b.drop : b[metric] - a[metric]);
    byId("screen-rows").innerHTML = renderRows(filtered);
    byId("results-count").textContent = `Showing ${filtered.length} of ${mixes.length} mixes`;
  }
  [wheelFilter, diverseFilter, sort].forEach(control => control.addEventListener("change", updateMixes));
  byId("print-rows").innerHTML = renderRows(mixes);
  updateMixes();

  byId("print").addEventListener("click", () => window.print());
  byId("export").addEventListener("click", () => {
    const header = ["Beginner wheel sessions", "Handbuilding sessions", "Glazing workshop sessions",
      "Baseline direct margin USD", "Stress direct margin USD (one fewer attendee per session)", "Margin drop USD"];
    const rows = mixes.map(mix => [...mix.counts, mix.base, mix.stress, mix.drop]);
    const csv = [header, ...rows].map(row => row.join(",")).join("'"\\r\\n\") + \"\\r\\n\";
    const url = URL.createObjectURL(new Blob([csv], { type: \"text/csv;charset=utf-8\" }));
    const link = document.createElement(\"a\");
    link.href = url;
    link.download = \"ceramics-schedule-mixes.csv\";
    document.body.append(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
</script>
</body>
</html>
